{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Apixaban has an absolute oral bioavailability of 51% in humans after a 2.5 mg oral dose, directly exceeding the 20% threshold and supporting high F for a moderately lipophilic, heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Ampicillin absolute bioavailability was 64.5 ± 17.4% in subjects, showing that even polar beta-lactam-like structures can achieve oral F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tamoxifen has almost 100% oral bioavailability in patients, demonstrating that lipophilic amine-containing drugs can have essentially complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide, a basic amide with first-pass metabolism, has an absolute oral bioavailability of 32 ± 7% in normal subjects, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "The active metabolite of nabumetone has a mean absolute oral bioavailability of 38% in healthy subjects, supporting F >20% for moderately lipophilic compounds with first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer experimental analogues report absolute oral bioavailability values above 20%, mostly in the 30-100% range. The query molecule is a lipophilic benzothiazepine with a basic side chain and ester group, consistent with these compounds. Although the modified-release formulation may alter absorption rate, the weight of evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself was retrieved.",
    "The modified-release formulation condition is not directly represented in the retrieved evidence, so formulation-specific effects on extent of absorption are inferred rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

